components.css:
.ds-action { display: inline-flex; box-sizing: border-box; align-items: center; justify-content: center; gap: .75rem; min-block-size: 2.95rem; padding: .65rem 1.15rem; border: 1px solid transparent; border-radius: 2rem; font: 700 1rem/1.25 var(--font-body); text-decoration: none; transition: transform 160ms var(--ease-out), background-color 160ms ease; }
.ds-action:active:not(:disabled) { transform: scale(.97); }
.ds-action:disabled { opacity: .7; cursor: wait; }
.ds-action:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-action { transition: none; } .ds-action:active:not(:disabled) { transform: none; } }
.ds-arrow { flex: 0 0 .82rem; inline-size: .82rem; block-size: .82rem; }
.ds-arrow-down { rotate: 90deg; }
:dir(rtl) .ds-arrow-inline { rotate: 180deg; }
.ds-action-primary { color: var(--on-action); background: var(--action); }
.ds-action-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--action), var(--on-action) 12%); }

.ds-action { display: inline-flex; box-sizing: border-box; align-items: center; justify-content: center; gap: .75rem; min-block-size: 2.95rem; padding: .65rem 1.15rem; border: 1px solid transparent; border-radius: 2rem; font: 700 1rem/1.25 var(--font-body); text-decoration: none; transition: transform 160ms var(--ease-out), background-color 160ms ease; }
.ds-action:active:not(:disabled) { transform: scale(.97); }
.ds-action:disabled { opacity: .7; cursor: wait; }
.ds-action:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-action { transition: none; } .ds-action:active:not(:disabled) { transform: none; } }
.ds-action-outline { color: var(--ink); border-color: var(--line); }
.ds-action-outline:hover { background: var(--field); }

.ds-copy { box-sizing: border-box; min-block-size: 2.75rem; padding: .35rem .7rem; border: 1px solid var(--line); border-radius: 2rem; color: var(--ink); background: transparent; font: 400 1rem/1.65 var(--font-body); cursor: pointer; }
.ds-copy:hover { background: var(--field); }
.ds-copy:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }

.ds-fields { display: grid; gap: .95rem; }
.ds-field { display: grid; gap: .25rem; color: var(--ink); font: 700 1rem/1.65 var(--font-body); }
.ds-field input, .ds-field textarea { box-sizing: border-box; inline-size: 100%; min-block-size: 2.8rem; padding: .65rem .8rem; border: 1px solid var(--control-line); border-radius: .65rem; color: var(--ink); background: var(--field); caret-color: var(--focus); font: 400 1rem/1.65 var(--font-body); }
.ds-field textarea { resize: vertical; }
.ds-field input:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
.ds-field textarea:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }

.ds-nav { display: flex; align-items: center; gap: clamp(1rem, 3vw, 2.25rem); }
.ds-nav a { display: grid; place-items: center; min-block-size: 2.75rem; white-space: nowrap; color: var(--muted); font: 400 .95rem/1.65 var(--font-body); text-decoration: underline transparent; text-underline-offset: .27em; }
.ds-nav a:hover { color: var(--ink); text-decoration-color: currentColor; }
.ds-nav a:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
@media (max-width: 45rem) { .ds-nav { justify-content: space-between; gap: .7rem; } }

.ds-lead { display: block; overflow: hidden; border-radius: var(--surface-radius); color: var(--hero-text); background: var(--hero-stage); font: 400 1rem/1.65 var(--font-body); text-decoration: none; }
.ds-lead-art { position: relative; isolation: isolate; overflow: hidden; aspect-ratio: 1.56; }
.ds-lead-art::before { position: absolute; z-index: -1; inset: 14% auto auto 34%; inline-size: 82%; aspect-ratio: 1; border-radius: 50%; background: var(--hero-plane); content: ""; }
.ds-lead-desktop, .ds-lead-phone { position: absolute; display: block; block-size: auto; }
.ds-lead-desktop { inset-block-start: 19%; inset-inline-start: 8%; inline-size: 79%; border: 1px solid rgb(255 255 255 / 22%); border-radius: .52rem; box-shadow: var(--device-shadow); }
.ds-lead-phone { inset-block-start: 14%; inset-inline-end: 9%; inline-size: 25%; filter: drop-shadow(0 15px 16px rgb(5 19 14 / 35%)); transition: transform 240ms var(--ease-out); }
.ds-lead:hover .ds-lead-phone { transform: translateY(-.35rem); }
.ds-lead-caption { display: flex; box-sizing: border-box; align-items: center; justify-content: space-between; gap: 1rem; min-block-size: 4.65rem; margin-inline: 1.25rem; padding-block: .65rem; border-block-start: 1px solid rgb(255 255 255 / 22%); }
.ds-lead-caption strong, .ds-lead-caption div span { display: block; }
.ds-lead-caption strong { font-size: 1.13rem; }
.ds-lead-caption div span { color: var(--hero-muted); font-size: .88rem; }
.ds-round-arrow { display: inline-grid; box-sizing: border-box; flex: 0 0 2.65rem; place-items: center; inline-size: 2.65rem; block-size: 2.65rem; border: 1px solid var(--line); border-radius: 50%; transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease; }
.ds-lead-caption .ds-round-arrow { color: var(--hero-accent-ink); background: var(--hero-accent); border-color: var(--hero-accent); }
.ds-arrow { flex: 0 0 .82rem; inline-size: .82rem; block-size: .82rem; }
.ds-arrow-down { rotate: 90deg; }
:dir(rtl) .ds-arrow-inline { rotate: 180deg; }
.ds-lead:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
@media (max-width: 45rem) { .ds-lead-caption { min-block-size: 3.95rem; margin-inline: .9rem; } }
@media (prefers-reduced-motion: reduce) { .ds-lead-phone, .ds-lead-caption .ds-round-arrow { transition: none; } .ds-lead:hover .ds-lead-phone { transform: none; } }

.ds-work { display: flex; flex-direction: column; color: var(--ink); font: 400 1rem/1.65 var(--font-body); text-decoration: none; }
.ds-work-art { position: relative; isolation: isolate; overflow: hidden; aspect-ratio: 1.62; border-radius: var(--surface-radius); background: var(--sand); }
.ds-work-phone { position: absolute; display: block; inline-size: 25%; block-size: auto; filter: drop-shadow(0 13px 12px rgb(13 24 18 / 22%)); transition: transform 240ms var(--ease-out); }
.ds-work-leading { inset-block-start: 11%; inset-inline-start: 23%; }
.ds-work-trailing { z-index: -1; inset-block-start: 22%; inset-inline-end: 24%; }
.ds-work:hover .ds-work-leading { transform: translateY(-.3rem); }
.ds-work-info { display: flex; justify-content: space-between; gap: .85rem; padding-block-start: 1rem; }
.ds-work-info h3 { margin: 0; font-size: clamp(1.6rem, 2.5vw, 2.35rem); line-height: 1.25; }
.ds-work-info p { margin: .35rem 0 0; color: var(--muted); }
.ds-work-type { font-size: .86rem; font-weight: 700; }
.ds-round-arrow { display: inline-grid; box-sizing: border-box; flex: 0 0 2.65rem; place-items: center; inline-size: 2.65rem; block-size: 2.65rem; border: 1px solid var(--line); border-radius: 50%; transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease; }
.ds-work:hover .ds-round-arrow { color: var(--on-action); background: var(--action); border-color: var(--action); }
.ds-arrow { flex: 0 0 .82rem; inline-size: .82rem; block-size: .82rem; }
.ds-arrow-down { rotate: 90deg; }
:dir(rtl) .ds-arrow-inline { rotate: 180deg; }
.ds-work:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-work-phone, .ds-work .ds-round-arrow { transition: none; } .ds-work:hover .ds-work-leading { transform: none; } }

.ds-archive { border-block-start: 1px solid var(--line); color: var(--ink); font: 400 1rem/1.65 var(--font-body); }
.ds-archive summary, .ds-archive a { display: flex; box-sizing: border-box; align-items: center; justify-content: space-between; gap: 1rem; min-block-size: 3.5rem; }
.ds-archive summary { list-style: none; font-weight: 700; cursor: pointer; }
.ds-archive summary::-webkit-details-marker { display: none; }
.ds-chevron { inline-size: .72rem; block-size: .72rem; margin-inline-end: .2rem; border-block-end: 1.5px solid currentColor; border-inline-end: 1.5px solid currentColor; rotate: 45deg; }
:dir(rtl) .ds-chevron { rotate: -45deg; }
.ds-archive[open] .ds-chevron { rotate: -135deg; }
.ds-archive[open]:dir(rtl) .ds-chevron { rotate: 135deg; }
.ds-archive a { flex-wrap: wrap; column-gap: 1.25rem; row-gap: .2rem; padding-block: .75rem; border-block-start: 1px solid var(--line); color: inherit; text-decoration: none; }
.ds-archive a span { color: var(--muted); font-size: .9rem; }
.ds-archive a:hover strong { text-decoration: underline; text-underline-offset: .25em; }
.ds-archive summary:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
.ds-archive a:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }

.ds-shot { display: grid; place-items: center; border: 1px solid var(--line); border-radius: 1rem; padding: clamp(.45rem, 1.5vw, 1.05rem); background: var(--field); text-decoration: none; }
.ds-shot img { display: block; inline-size: 100%; block-size: min(65vw, 24rem); object-fit: contain; }
.ds-shot:hover { border-color: var(--focus); }
.ds-shot:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
